// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory data) public {
        vm.assume(callee != address(0) && callee != address(c));
        Attacker helper = new Attacker();
        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", address(helper), data));
        assertTrue(!helper.called() == !ok);
    }
}
contract Attacker {
    bool public called;
    fallback() external payable { called = true; }
}
